+        }
+    }
+
+    interface Parameters extends WorkParameters {
+        ConfigurableFileCollection getClassDirectories();
+
+        ConfigurableFileCollection getClasspath();
+
+        ListProperty<String> getSuffixes();
+
+        ListProperty<String> getBaseClassesNames();
+    }
+}
