+                    + v
+                    + "] with type ["
+                    + v.getClass().getName()
+                    + "]"
+            );
+        }),
+        VERSION,
+        new FieldProperty<>(Number.class, false, true, FieldProperty.LONGABLE_NUMBER),
+        TYPE,
+        new FieldProperty<>(String.class, true, false, null),
+        IF_SEQ_NO,
